  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --font-size: 100%;
  --line-height: 1.6;
  --dark-bg: #1a1a2e;
  --dark-surface: #16213e;
  --dark-text: #e8e8e8;
  --dark-muted: #8892b0;
  --dark-border: #62719d;
  --dark-focus: #64ffda;
  --dark-primary: #64ffda;
  --dark-primary-hover: #45e0be;
  --dark-error: #ff6b6b;
  --dark-success: #51cf66;
  --dark-warn: #ffd43b;
  --dark-highlight: #1e2d50;

