  --error-ink: var(--error);
  --success-ink: var(--success);
  --accent-ink: var(--accent);
  --warn-ink: var(--warn);
  --on-accent: var(--bg);
  --primary: var(--dark-primary);
  --primary-hover: var(--dark-primary-hover);
  --primary-ink: var(--dark-bg);
  --toast-bg: var(--dark-surface);
  --toast-ink: var(--dark-text);
  --on-error: var(--bg);
  --on-success: var(--bg);
  --table-header: transparent;
  --table-header-ink: #fff;
  --table-hover: var(--surface);
  --field: var(--dark-bg);
  --focus: var(--dark-focus);
  --sidepanel-bg: var(--dark-surface);
  --sidepanel-ink: var(--dark-text);
  --status-bg: var(--surface);
  --status-ink: var(--text);
}

*, *::before, *::after { box-sizing: border-box; }

